import { Capacitor } from '@capacitor/core';

/** Dispatched on window when a new app version is downloaded and waiting (see UpdateBanner). */
export const UPDATE_AVAILABLE_EVENT = 'app-update-available';

/** Cache of the hand-written service worker used before vite-plugin-pwa; Workbox does not know it. */
const LEGACY_CACHE_NAME = 'property-rental-v2';

let activateWaitingVersion: ((reloadPage?: boolean) => Promise<void>) | null = null;

/**
 * Register the service worker (generated by vite-plugin-pwa) on the web. Native apps ship their
 * files inside the app, so a cache there could only serve the previous version after a store
 * update; any worker an older build registered in the app is removed.
 */
export async function setUpServiceWorker(): Promise<void> {
  if (!('serviceWorker' in navigator)) return;

  if (Capacitor.isNativePlatform()) {
    const registrations = await navigator.serviceWorker.getRegistrations();
    await Promise.all(registrations.map((registration) => registration.unregister()));
    return;
  }

  if (typeof caches !== 'undefined') {
    caches.delete(LEGACY_CACHE_NAME).catch(() => {
      // Nothing to clean up, or storage unavailable: either way nothing else to do.
    });
  }

  const { registerSW } = await import('virtual:pwa-register');
  activateWaitingVersion = registerSW({
    onNeedRefresh: () => window.dispatchEvent(new CustomEvent(UPDATE_AVAILABLE_EVENT)),
    onRegisterError: (error: unknown) => console.error('Service worker registration failed:', error),
  });
}

/** Switch to the waiting version and reload. Falls back to a plain reload. */
export function applyUpdate(): void {
  if (activateWaitingVersion) {
    activateWaitingVersion(true).catch(() => window.location.reload());
  } else {
    window.location.reload();
  }
}
